input.command:
@'
schema_version: 1
product: clinica-piloto
gates:
  test_environment: {value: true, source: carta, quote: 'lab (laboratório local, sem dados reais de pessoas)'}
  synthetic_data: {value: true, source: carta, quote: 'laboratório local, sem dados reais de pessoas'}
  authorization_in_force: {value: true, source: carta, quote: 'Válida até: 2027-12-31'}
  product_owner: {value: 'time Clínica Piloto', source: carta}
environment:
  name: {value: lab, source: carta}
  base_url: {value: 'http://clinica-piloto:8080', source: carta}
  openapi: {value: ./openapi.json, source: carta, quote: 'OpenAPI: inputs/openapi.json'}
scope:
  allow:
    value:
      - host: clinica-piloto
        scheme: http
        port: 8080
        allow_local: true
        paths: ['/api/**', '/v3/api-docs']
        methods: [GET, POST, PUT, PATCH]
    source: carta
    quote: 'Host: clinica-piloto, porta 8080, http; Caminhos autorizados: /api/** e /v3/api-docs; Métodos autorizados: GET, POST, PUT e PATCH'
  deny_paths: {value: ['/api/notificacoes/**', '/api/isca/**'], source: carta}
  path_mode: {value: wide, source: carta, quote: 'Modo de leitura de caminhos pela cerca: AMPLO (wide), autorizado pelo dono do laboratório nesta sessão em 2026-11-14 para esta nova rodada cega.'}
authorization:
  reference: {value: LAB-CLINICA-PILOTO, source: carta}
  valid_until: {value: 2027-12-31, source: carta}
  windows: {value: ['seg-dom 00:00-24:00 America/Sao_Paulo'], source: carta}
limits:
  requests_per_second: {value: 20, source: carta}
  max_duration_minutes: {value: 30, source: carta}
  zap_threads_per_host: {value: 4, source: carta}
auth:
  type: {value: login_password, source: carta}
  token_path: {value: /api/auth/login, source: carta}
  login_max_per_minute: {value: 5, source: carta}
  accounts:
    source: carta
    value:
      - alias: admin_a
        role: admin
        username: {secret_ref: 'env:PILOT_ADMIN_USERNAME'}
        password: {secret_ref: 'env:PILOT_ADMIN_PASSWORD'}
      - alias: medico_a
        role: medico
        username: {secret_ref: 'env:PILOT_MEDICO_USERNAME'}
        password: {secret_ref: 'env:PILOT_MEDICO_PASSWORD'}
      - alias: paciente_a
        role: paciente
        username: {secret_ref: 'env:PILOT_PACIENTE_A_USERNAME'}
        password: {secret_ref: 'env:PILOT_PACIENTE_A_PASSWORD'}
      - alias: paciente_b
        role: paciente
        username: {secret_ref: 'env:PILOT_PACIENTE_B_USERNAME'}
        password: {secret_ref: 'env:PILOT_PACIENTE_B_PASSWORD'}
'@ | Set-Content -Encoding utf8 clinica-piloto.carta.yml
New-Item -ItemType Directory -Force products | Out-Null
uv run hdast --json init clinica-piloto --from-letter clinica-piloto.carta.yml --products-dir ./products --check

$path = 'products/clinica-piloto/target.yml'
$content = Get-Content $path -Raw
$content = $content.Replace('  token_path: "/api/auth/login"', "  token_path: `"/api/auth/login`"`n  request_encoding: json`n  csrf:`n    fetch_path: /api/csrf`n  account_map:`n    - {account: medico_a, path: /api/pacientes/**}`n    - {account: medico_a, path: /api/pacientes}`n    - {account: medico_a, path: /api/consultas/**}`n    - {account: medico_a, path: /api/consultas}`n    - {account: medico_a, path: /api/receitas/**}`n    - {account: medico_a, path: /api/receitas}`n    - {account: paciente_a, path: /api/me}")
$content += "`nprobe:`n  health_path: /api/saude`n"
Set-Content -Encoding utf8 $path $content
@'
schema_version: 1
bindings:
  - produces: {operation: criarConvenio, field: id}
    consumed_by:
      - {operation: buscarConvenio, param: id}
      - {operation: atualizarConvenio, param: id}
      - {operation: criarPaciente, field: convenioId}
      - {operation: atualizarPaciente, field: convenioId}
  - produces: {operation: criarMedico, field: id}
    consumed_by:
      - {operation: buscarMedico, param: id}
      - {operation: criarConsulta, field: medicoId}
  - produces: {operation: criarPaciente, field: id}
    consumed_by:
      - {operation: buscarPaciente, param: id}
      - {operation: atualizarPaciente, param: id}
      - {operation: criarConsulta, field: pacienteId}
  - produces: {operation: criarConsulta, field: id}
    consumed_by:
      - {operation: buscarConsulta, param: id}
      - {operation: listarReceitasDaConsulta, param: id}
      - {operation: atualizarStatusConsulta, param: id}
      - {operation: criarReceita, field: consultaId}
  - produces: {operation: criarReceita, field: id}
    consumed_by:
      - {operation: buscarReceita, param: id}
'@ | Set-Content -Encoding utf8 products/clinica-piloto/flows.yml
uv run hdast --json profile validate clinica-piloto --products-dir ./products
uv run hdast --json spec inspect clinica-piloto --products-dir ./products | python -c "import json,sys; d=json.load(sys.stdin)['data']; print(json.dumps({k:d[k] for k in ('issues','needs_rule','unused_rules','servers_out_of_scope')},ensure_ascii=False))"
uv run hdast --json profile approval clinica-piloto --products-dir ./products

